CREATE TABLE invoice_application (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, application_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, invoice_type VARCHAR(32) NOT NULL, title VARCHAR(256) NOT NULL, tax_no_ciphertext VARCHAR(512) NULL, bank_name VARCHAR(256) NULL, bank_account_ciphertext VARCHAR(512) NULL, registered_address VARCHAR(512) NULL, registered_phone_ciphertext VARCHAR(512) NULL, requested_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, submitted_by BIGINT NULL, submitted_at DATETIME(3) NULL, approved_by BIGINT NULL, approved_at DATETIME(3) NULL, provider_request_no VARCHAR(128) NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_inv_app(tenant_id,application_no), UNIQUE KEY uk_inv_provider_req(provider_request_no));
CREATE TABLE invoice_application_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, application_id BIGINT NOT NULL, allocation_id BIGINT NOT NULL, requested_amount DECIMAL(18,2) NOT NULL, KEY idx_invapp_alloc(tenant_id,allocation_id));
CREATE TABLE invoice (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, invoice_no VARCHAR(128) NOT NULL, application_id BIGINT NOT NULL, provider VARCHAR(32) NOT NULL, provider_invoice_id VARCHAR(128) NULL, invoice_type VARCHAR(32) NOT NULL, blue_or_red VARCHAR(8) NOT NULL, amount DECIMAL(18,2) NOT NULL, tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL, issued_at DATETIME(3) NULL, pdf_file_id BIGINT NULL, ofd_file_id BIGINT NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by BIGINT NULL, updated_by BIGINT NULL, UNIQUE KEY uk_invoice_no(tenant_id,invoice_no), UNIQUE KEY uk_provider_invoice(provider,provider_invoice_id));
CREATE TABLE invoice_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, invoice_id BIGINT NOT NULL, item_name VARCHAR(256) NOT NULL, tax_rate DECIMAL(20,8) NULL, amount DECIMAL(18,2) NOT NULL, tax_amount DECIMAL(18,2) NOT NULL, KEY idx_invoice_item(tenant_id,invoice_id));
CREATE TABLE invoice_relation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, source_invoice_id BIGINT NOT NULL, target_invoice_id BIGINT NOT NULL, relation_type VARCHAR(32) NOT NULL, UNIQUE KEY uk_inv_relation(tenant_id,source_invoice_id,target_invoice_id,relation_type));
CREATE TABLE invoice_red_flush_application (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, application_no VARCHAR(64) NOT NULL, original_invoice_id BIGINT NOT NULL, reason VARCHAR(512) NOT NULL, requested_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, workflow_instance_id VARCHAR(128) NULL, provider_request_no VARCHAR(128) NULL, created_at DATETIME(3) NOT NULL, UNIQUE KEY uk_red_app(tenant_id,application_no), UNIQUE KEY uk_red_provider_req(provider_request_no));
